mapper.select:
SELECT r.id, r.user_id AS userId, u.nickname, u.avatar, u.checkin_days AS checkinDays, r.book_id AS bookId, b.title AS bookTitle, r.chapter_title AS chapterTitle, r.checkin_type AS checkinType, r.content, r.media_url AS mediaUrl, r.audio_url AS audioUrl, r.audio_duration AS audioDuration, r.like_count AS likeCount, r.comment_count AS commentCount, r.view_count AS viewCount, r.checkin_date AS checkinDate, r.create_time AS createTime FROM checkin_record r LEFT JOIN sys_user u ON r.user_id = u.id LEFT JOIN book b ON r.book_id = b.id WHERE r.is_public = 1 AND r.status = 1 AND r.deleted = 0
AND r.circle_id IN
#{circleId}
AND r.checkin_type = #{checkinType}
ORDER BY r.create_time DESC
